import React from 'react';

function Contact() {
  return (
    <section id="contact">
      <h2 className="section-heading">Contact Me</h2>
      <div className="contact-info">
        <p>Email: <a href="mailto:ihn10@txstate.edu">ihn10@txstate.edu</a></p>
        <p>Phone: <a href="tel:+17372132760">+1 (737) 213-2760</a></p>
        <p>LinkedIn: <a href="https://www.linkedin.com/in/sachin-pandey-50244a271/" target="_blank" rel="noreferrer">linkedin.com/in/sachin-pandey</a></p>
        <p>GitHub: <a href="https://github.com/" target="_blank" rel="noreferrer">github.com/sachinpandey</a> (placeholder)</p>
      </div>
    </section>
  );
}

export default Contact;
